package com.personal.meditation;
import android.content.*;import org.json.*;
final class Settings {
 static final String[] KEYS={"prepShort","prepLong","start","quarter","end"};static final int[] LENGTHS={90,600,150,150,900};
 static boolean isBundledZen(String name){return name!=null&&name.trim().matches("(?i)(?:alex_jauk-)?zen-tone-mid-high-202557(?:\\s*\\(\\d+\\))?\\.mp3");}
 private String choice(String role){String value=prefs.getString(role,"soft_bell");return value.equals("custom")&&isBundledZen(prefs.getString(role+"Name",""))?"zen_tone":value;}
 final android.content.SharedPreferences prefs;Settings(Context context){prefs=context.getSharedPreferences("meditation_settings",0);}
 static final String[] COLORS={"backgroundTop","backgroundBottom","accentTop","accentBottom"};
 static final String[] DEFAULT_COLORS={"#203747","#5a5c61","#f4f7fa","#f4f7fa"};
 static boolean validColor(String value){return value!=null&&value.matches("#[0-9a-fA-F]{6}");}
 private JSONObject appearance()throws JSONException{JSONObject value=new JSONObject();for(int i=0;i<COLORS.length;i++)value.put(COLORS[i],prefs.getString(COLORS[i],DEFAULT_COLORS[i]));return value.put("backgroundGradient",prefs.getBoolean("backgroundGradient",true)).put("accentGradient",prefs.getBoolean("accentGradient",false));}
 JSONObject get(){try{JSONObject out=new JSONObject().put("minutes",prefs.getInt("minutes",10)).put("intervals",prefs.getInt("intervals",4));for(String role:new String[]{"bell","quarter"})out.put(role,choice(role)).put(role+"Name",prefs.getString(role+"Name","Chosen audio file")).put(role+"HasCustom",!prefs.getString(role+"Uri","").isEmpty());JSONObject h=new JSONObject();for(int i=0;i<KEYS.length;i++)h.put(KEYS[i],new JSONObject().put("enabled",prefs.getBoolean(KEYS[i]+"Enabled",i!=2)).put("ms",prefs.getInt(KEYS[i]+"Ms",LENGTHS[i])));return out.put("vibrations",h).put("appearance",appearance());}catch(JSONException invalid){throw new IllegalStateException(invalid);}}
 boolean save(String raw){try{JSONObject data=new JSONObject(raw);Object minutes=data.get("minutes");if(!(minutes instanceof Integer)||(int)minutes<1||(int)minutes>240)return false;Object intervals=data.has("intervals")?data.get("intervals"):prefs.getInt("intervals",4);if(!(intervals instanceof Integer)||(int)intervals<1||(int)intervals>6)return false;android.content.SharedPreferences.Editor edit=prefs.edit().putInt("minutes",(int)minutes).putInt("intervals",(int)intervals);for(String role:new String[]{"bell","quarter"}){String sound=data.getString(role);if(!sound.equals("soft_bell")&&!sound.equals("warm_bowl")&&!sound.equals("gentle_chime")&&!sound.equals("temple_gong")&&!sound.equals("zen_tone")&&!sound.equals("silent")&&!(sound.equals("custom")&&!prefs.getString(role+"Uri","").isEmpty()))return false;edit.putString(role,sound);}JSONObject h=data.getJSONObject("vibrations");for(int i=0;i<KEYS.length;i++){JSONObject value=h.getJSONObject(KEYS[i]);Object length=value.get("ms"),enabled=value.get("enabled");int maximum=i<2?900:5000;if(!(length instanceof Integer)||(int)length<50||(int)length>maximum||!(enabled instanceof Boolean))return false;edit.putInt(KEYS[i]+"Ms",(int)length).putBoolean(KEYS[i]+"Enabled",(boolean)enabled);}if(data.has("appearance")){JSONObject appearance=data.getJSONObject("appearance");for(String key:COLORS){Object value=appearance.get(key);if(!(value instanceof String)||!validColor((String)value))return false;edit.putString(key,((String)value).toLowerCase(java.util.Locale.ROOT));}for(String key:new String[]{"backgroundGradient","accentGradient"}){Object value=appearance.get(key);if(!(value instanceof Boolean))return false;edit.putBoolean(key,(boolean)value);}}return edit.commit();}catch(JSONException|RuntimeException failed){return false;}}
 boolean custom(String role,String uri,String label){if(!role.equals("bell")&&!role.equals("quarter"))return false;return prefs.edit().putString(role,isBundledZen(label)?"zen_tone":"custom").putString(role+"Uri",uri).putString(role+"Name",label).commit();}
}
